// Email-specific labels. Web-relevant labels are handled by mozilla::Encoding.
// Labels must be lowercase; names must be canonical encoding names or UTF-7.
static constexpr struct {
  nsLiteralCString label;
  nsLiteralCString name;
} kAliases[] = {
    // Added for Solaris ns_langinfo. Unlikely relevant to email.
    // https://bugzilla.mozilla.org/show_bug.cgi?id=77300#c9
    {"646"_ns, "windows-1252"_ns},

    // Aliases for ISO-8859-8-I
    // From the original IBM bidi patch.
    {"iso-8859-8i"_ns, "ISO-8859-8-I"_ns},

    // ISO 8859 series with underscore for JavaMail
    // compat.
    // https://bugzilla.mozilla.org/show_bug.cgi?id=820767
    {"iso8859_1"_ns, "windows-1252"_ns},
    {"iso8859_2"_ns, "ISO-8859-2"_ns},
    {"iso8859_3"_ns, "ISO-8859-3"_ns},
    {"iso8859_4"_ns, "ISO-8859-4"_ns},
    {"iso8859_5"_ns, "ISO-8859-5"_ns},
